def catalogo():
    """→ {id: {nombre, tags, familia}}"""
    import json, os
    out = {}
    for fam, d in FAMILIAS.items():
        for k, (n, t) in d.items(): out[k] = {"nombre": n, "tags": t, "familia": fam}
    try:
        for e in json.load(open(os.path.join(os.path.dirname(os.path.abspath(__file__)), "estilos-web.json"))): out.setdefault(e["id"], {"nombre": e["nombre"], "tags": e["tags"], "familia": "Estilos de Island Crew"})
    except Exception: pass
    return out
